 * indefinite-length array (`9f`), the version (`01`), the state as an indefinite-length map, and a
 * break (`ff`). Editable until format 1 ships, then frozen as [GOLDEN_FORMAT_1] is.
 */
internal const val GOLDEN_FORMAT_1_CBOR: String = ""

/**
